\begin{gathered}

P(X_1 = x_1, X_2 = x_2, \cdots, X_n = x_n | Y=y) \\
\\
= \frac { P(X_1 = x_1, X_2 = x_2, \cdots, X_n = x_n, Y=y) } { P(Y=y) } \\
\\
= \frac {\theta^{\sum x_i}(1-\theta)^{n-\sum x_i}} {\binom n y \theta^y (1-\theta)^{n-y}}\\
\\
= \frac 1 {\binom n y} = \frac{(n-y)! y!}{n!}

\end{gathered}
